INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('10f51532-d615-5afb-9af6-1d5eedd7dda3','be316218-b315-57d6-afc9-2237fdc128d1','tr','İhracat Radarı — Dış Ticaret İstihbaratı ve İhracat CRM SaaS','ihracat-radari-dis-ticaret-istihbarati-saas','Gerçek sevkiyat kayıtlarından alıcı bulma, ihracat evrakı üretimi ve alıcıyla temas süreçlerini tek panelde toplayan çok kiracılı SaaS.','{"html": "<p><strong>İhracat Radarı</strong>, Türk KOBİ ve sanayi firmalarının dış ticaret operasyonunu tek panelde toplar. HS/GTİP koduyla arama yapılır; gümrük kayıtlarından alıcı firmalar, miktarlar ve işlem geçmişi çıkarılır.</p><h2>Gerçek veriden alıcı bulma</h2><p>Gümrük beyanlarına dayanan sevkiyat kayıtları ülke, ürün ve firma bazında analiz edilir. Her aday firma, eşleşme nedeni ve kaynağıyla birlikte sunulur.</p><h2>İhracat CRM ve evrak</h2><p>Firma kartı, fırsat hattı ve görev takibinin yanında proforma fatura, ticari fatura ve çeki listesi aynı sistemde üretilir.</p><h2>Yapay zekâ destekli arama planı</h2><p>Ülke, sektör ve firma türü netleştirilir; kredi ve süre önizlemesi kullanıcı onayından sonra çalışır. Sonuçlar puanlanır ve onay akışından geçer.</p><h2>Öne çıkan özellikler</h2><ul><li>HS/GTİP kodu bazlı alıcı ve rakip istihbaratı</li><li>Gümrük kayıtlarından sevkiyat analizi</li><li>Proforma, ticari fatura ve çeki listesi üretimi</li><li>Alıcı listelerine toplu e-posta ve yanıt takibi</li><li>Aday firma puanlama ve onay akışı</li><li>Çok kiracılı yapı ve kredi tabanlı kullanım</li></ul>", "description": "Gerçek sevkiyat kayıtlarından alıcı bulma, ihracat evrakı üretimi ve alıcıyla temas süreçlerini tek panelde toplayan çok kiracılı SaaS.", "key_features": ["HS/GTİP kodu bazlı alıcı ve rakip istihbaratı", "Gümrük kayıtlarından sevkiyat analizi", "Proforma, ticari fatura ve çeki listesi üretimi", "Alıcı listelerine toplu e-posta ve yanıt takibi", "Aday firma puanlama ve onay akışı", "Çok kiracılı yapı ve kredi tabanlı kullanım"], "technologies_used": ["Next.js 16", "React 19", "TypeScript", "Fastify 5", "Bun", "Drizzle ORM", "MariaDB", "Python", "Tailwind CSS 4", "Groq LLM"], "design_highlights": []}','İhracat Radarı ana sayfası: HS kodu ile alıcı arama','İhracat Radarı — Dış Ticaret İstihbaratı SaaS | Guezel Web Design','HS/GTİP koduyla gerçek sevkiyat kayıtlarından alıcı bulan, ihracat evrakı üreten ve alıcı temasını yöneten çok kiracılı dış ticaret SaaS platformu.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
