INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('348aa8ff-b521-5f3c-a9f7-d993d154998d','be316218-b315-57d6-afc9-2237fdc128d1','en','İhracat Radarı — Trade Intelligence and Export CRM SaaS','ihracat-radari-dis-ticaret-istihbarati-saas','A multi-tenant SaaS that finds buyers from real shipment records, generates export documents and manages buyer outreach in a single panel.','{"html": "<p><strong>İhracat Radarı</strong> brings the foreign trade operations of Turkish SMEs and manufacturers into one panel. Users search by HS code and see buyer companies, volumes and transaction history extracted from customs records.</p><h2>Buyer discovery from real data</h2><p>Customs-based shipment records are analysed by country, product and company. Every candidate comes with its source and the reason it matched.</p><h2>Export CRM and documents</h2><p>Company cards, an opportunity pipeline and task tracking sit next to proforma invoices, commercial invoices and packing lists generated in the same system.</p><h2>AI-assisted search planning</h2><p>Country, sector and company type are clarified first; credit and duration previews run only after user approval. Results are scored and pass through an approval flow.</p><h2>Key features</h2><ul><li>HS-code based buyer and competitor intelligence</li><li>Shipment analysis from customs records</li><li>Proforma, commercial invoice and packing list generation</li><li>Bulk email outreach with reply tracking</li><li>Candidate scoring and approval flow</li><li>Multi-tenant, credit-based usage</li></ul>", "description": "A multi-tenant SaaS that finds buyers from real shipment records, generates export documents and manages buyer outreach in a single panel.", "key_features": ["HS-code based buyer and competitor intelligence", "Shipment analysis from customs records", "Proforma, commercial invoice and packing list generation", "Bulk email outreach with reply tracking", "Candidate scoring and approval flow", "Multi-tenant, credit-based usage"], "technologies_used": ["Next.js 16", "React 19", "TypeScript", "Fastify 5", "Bun", "Drizzle ORM", "MariaDB", "Python", "Tailwind CSS 4", "Groq LLM"], "design_highlights": []}','İhracat Radarı homepage: buyer search by HS code','İhracat Radarı — Trade Intelligence SaaS | Guezel Web Design','Multi-tenant foreign trade SaaS that finds buyers from real shipment records by HS code, generates export documents and manages buyer outreach.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
