INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('3764719e-f421-50df-8cad-a43e49b18710','be316218-b315-57d6-afc9-2237fdc128d1','de','İhracat Radarı — Außenhandels-Intelligence und Export-CRM als SaaS','ihracat-radari-dis-ticaret-istihbarati-saas','Eine mandantenfähige SaaS, die Käufer aus realen Lieferdaten findet, Exportdokumente erstellt und die Käuferansprache in einem Panel bündelt.','{"html": "<p><strong>İhracat Radarı</strong> bündelt den Außenhandel türkischer KMU und Industrieunternehmen in einem Panel. Gesucht wird per HS-Code; Käuferfirmen, Mengen und Transaktionsverläufe stammen aus Zolldaten.</p><h2>Käufersuche auf Basis realer Daten</h2><p>Lieferdaten aus Zollanmeldungen werden nach Land, Produkt und Unternehmen ausgewertet. Jeder Kandidat erscheint mit Quelle und Begründung des Treffers.</p><h2>Export-CRM und Dokumente</h2><p>Firmenkarten, Opportunity-Pipeline und Aufgaben stehen neben Proforma-Rechnung, Handelsrechnung und Packliste, die im selben System erzeugt werden.</p><h2>KI-gestützte Suchplanung</h2><p>Land, Branche und Firmentyp werden zuerst geschärft; Kredit- und Zeitvorschau laufen erst nach Freigabe durch den Nutzer. Ergebnisse werden bewertet und freigegeben.</p><h2>Wichtige Funktionen</h2><ul><li>Käufer- und Wettbewerbsanalyse per HS-Code</li><li>Lieferanalyse aus Zolldaten</li><li>Proforma, Handelsrechnung und Packliste</li><li>Massen-E-Mails mit Antwortverfolgung</li><li>Kandidatenbewertung mit Freigabeprozess</li><li>Mandantenfähig mit Credit-Modell</li></ul>", "description": "Eine mandantenfähige SaaS, die Käufer aus realen Lieferdaten findet, Exportdokumente erstellt und die Käuferansprache in einem Panel bündelt.", "key_features": ["Käufer- und Wettbewerbsanalyse per HS-Code", "Lieferanalyse aus Zolldaten", "Proforma, Handelsrechnung und Packliste", "Massen-E-Mails mit Antwortverfolgung", "Kandidatenbewertung mit Freigabeprozess", "Mandantenfähig mit Credit-Modell"], "technologies_used": ["Next.js 16", "React 19", "TypeScript", "Fastify 5", "Bun", "Drizzle ORM", "MariaDB", "Python", "Tailwind CSS 4", "Groq LLM"], "design_highlights": []}','İhracat Radarı Startseite: Käufersuche per HS-Code','İhracat Radarı — Außenhandels-Intelligence SaaS | Guezel Web Design','Mandantenfähige Außenhandels-SaaS: findet Käufer per HS-Code aus realen Lieferdaten, erstellt Exportdokumente und steuert die Käuferansprache.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
