INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('565961d2-9254-5b1d-bb90-0132a21f341e','e5c5db93-1289-50f6-93fa-cf14e816a161','tr','mezarisim.com — Mezar Yapımı Katalog ve Teklif Platformu','mezarisim-mezar-yapimi-katalog-ve-teklif-platformu','İstanbul pazarı için mezar modelleri kataloğu, hizmet sayfaları, teklif akışı ve yönetim paneli içeren mezar yapımı ve bakım platformu.','{"html": "<p><strong>mezarisim.com</strong>, mezar yapımı ve mezar bakımı hizmeti veren bir işletme için geliştirilen katalog ve teklif platformudur. Ziyaretçi modeli seçer, hizmeti inceler ve doğrudan teklif ister.</p><h2>Model ve hizmet kataloğu</h2><p>Tek ve iki kişilik mermer ve granit modeller, baş taşı modelleri ve mezar aksesuarları kategorilere ayrılmış bir katalogda sunulur.</p><h2>Teklif ve iletişim akışı</h2><p>Ürün aramasından teklif formuna kadar her adım ziyaretçiyi işletmeyle buluşturacak şekilde kurgulandı; hızlı arama ve telefon bağlantıları her sayfada görünür.</p><h2>Yönetim paneli</h2><p>Modeller, kategoriler, görseller ve sayfa içerikleri yönetim panelinden güncellenir; medya Cloudinary üzerinden servis edilir.</p><h2>Öne çıkan özellikler</h2><ul><li>Model ve hizmet kataloğu</li><li>Ürün arama</li><li>Teklif ve iletişim akışları</li><li>Yönetim paneli</li><li>Cloudinary medya yönetimi</li><li>E-posta bildirimleri ve SEO uyumu</li></ul>", "description": "İstanbul pazarı için mezar modelleri kataloğu, hizmet sayfaları, teklif akışı ve yönetim paneli içeren mezar yapımı ve bakım platformu.", "key_features": ["Model ve hizmet kataloğu", "Ürün arama", "Teklif ve iletişim akışları", "Yönetim paneli", "Cloudinary medya yönetimi", "E-posta bildirimleri ve SEO uyumu"], "technologies_used": ["React", "TypeScript", "Vite", "Redux Toolkit", "React Query", "Shadcn UI", "Tailwind CSS", "Fastify", "Drizzle ORM", "MySQL"], "design_highlights": []}','mezarisim.com ana sayfası: mezar modelleri ve kategori menüsü','mezarisim.com — Mezar Yapımı Katalog ve Teklif Platformu | Guezel Web Design','Mezar modelleri kataloğu, hizmet sayfaları, teklif akışı ve yönetim paneli ile geliştirilen mezar yapımı ve bakım platformu: React, Fastify, MySQL.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
