INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('cb181141-2944-574a-9ca1-e6b990054f1e','e5c5db93-1289-50f6-93fa-cf14e816a161','en','mezarisim.com — Memorial Construction Catalog and Quote Platform','mezarisim-mezar-yapimi-katalog-ve-teklif-platformu','A memorial construction and grave care platform for the Istanbul market with a model catalog, service pages, quote flows and an admin panel.','{"html": "<p><strong>mezarisim.com</strong> is a catalog and quote platform built for a business offering memorial construction and grave care. Visitors choose a model, review the service and request a quote directly.</p><h2>Model and service catalog</h2><p>Single and double marble and granite models, headstone designs and accessories are organised into a categorised catalog.</p><h2>Quote and contact flow</h2><p>Every step from product search to the quote form is designed to connect the visitor with the business; quick search and call links are visible on every page.</p><h2>Admin panel</h2><p>Models, categories, images and page content are managed from the admin panel; media is served through Cloudinary.</p><h2>Key features</h2><ul><li>Model and service catalog</li><li>Product search</li><li>Quote and contact flows</li><li>Admin panel</li><li>Cloudinary media management</li><li>Email notifications and SEO</li></ul>", "description": "A memorial construction and grave care platform for the Istanbul market with a model catalog, service pages, quote flows and an admin panel.", "key_features": ["Model and service catalog", "Product search", "Quote and contact flows", "Admin panel", "Cloudinary media management", "Email notifications and SEO"], "technologies_used": ["React", "TypeScript", "Vite", "Redux Toolkit", "React Query", "Shadcn UI", "Tailwind CSS", "Fastify", "Drizzle ORM", "MySQL"], "design_highlights": []}','mezarisim.com homepage with memorial models and category menu','mezarisim.com — Memorial Catalog and Quote Platform | Guezel Web Design','Memorial construction and grave care platform with a model catalog, service pages, quote flow and admin panel, built with React, Fastify and MySQL.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `project_images_i18n` (`id`,`image_id`,`locale`,`alt`,`caption`,`created_at`,`updated_at`) VALUES ('e2a0ae9b-cc25-52ec-8396-aea6c6653091','0b610782-2a2f-5c34-a2c1-93b14172be39','en','mezarisim.com homepage with memorial models and category menu',NULL,NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `alt`=VALUES(`alt`),`updated_at`=NOW(3);
INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('3239b568-bbe6-5dee-8631-5a4cd7e10c61','e5c5db93-1289-50f6-93fa-cf14e816a161','de','mezarisim.com — Katalog- und Angebotsplattform für Grabgestaltung','mezarisim-mezar-yapimi-katalog-ve-teklif-platformu','Eine Plattform für Grabbau und Grabpflege im Istanbuler Markt mit Modellkatalog, Leistungsseiten, Angebotsprozess und Verwaltungsbereich.','{"html": "<p><strong>mezarisim.com</strong> ist eine Katalog- und Angebotsplattform für ein Unternehmen, das Grabanlagen errichtet und pflegt. Besucher wählen ein Modell, prüfen die Leistung und fordern direkt ein Angebot an.</p><h2>Modell- und Leistungskatalog</h2><p>Ein- und Zweipersonen-Modelle aus Marmor und Granit, Grabsteine und Zubehör sind in einem kategorisierten Katalog geordnet.</p><h2>Angebots- und Kontaktprozess</h2><p>Von der Produktsuche bis zum Angebotsformular führt jeder Schritt zum Unternehmen; Schnellsuche und Anruf-Links sind auf jeder Seite sichtbar.</p><h2>Verwaltungsbereich</h2><p>Modelle, Kategorien, Bilder und Seiteninhalte werden im Admin-Panel gepflegt; Medien laufen über Cloudinary.</p><h2>Wichtige Funktionen</h2><ul><li>Modell- und Leistungskatalog</li><li>Produktsuche</li><li>Angebots- und Kontaktprozesse</li><li>Admin-Panel</li><li>Medienverwaltung mit Cloudinary</li><li>E-Mail-Benachrichtigungen und SEO</li></ul>", "description": "Eine Plattform für Grabbau und Grabpflege im Istanbuler Markt mit Modellkatalog, Leistungsseiten, Angebotsprozess und Verwaltungsbereich.", "key_features": ["Modell- und Leistungskatalog", "Produktsuche", "Angebots- und Kontaktprozesse", "Admin-Panel", "Medienverwaltung mit Cloudinary", "E-Mail-Benachrichtigungen und SEO"], "technologies_used": ["React", "TypeScript", "Vite", "Redux Toolkit", "React Query", "Shadcn UI", "Tailwind CSS", "Fastify", "Drizzle ORM", "MySQL"], "design_highlights": []}','mezarisim.com Startseite mit Grabmodellen und Kategoriemenü','mezarisim.com — Katalog- und Angebotsplattform | Guezel Web Design','Plattform für Grabbau und Grabpflege mit Modellkatalog, Leistungsseiten, Angebotsprozess und Admin-Panel, umgesetzt mit React, Fastify und MySQL.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
