INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('34f230ec-3213-5f2b-86c5-47ed33edee43','a5713635-b3f4-5bcc-9582-421011585475','tr','Bayramözü Köyü — Kaynaklı Köy Tarihi ve Dijital Arşiv Platformu','bayramozu-koyu-dijital-arsiv-ve-koy-platformu','Kaman/Kırşehir''e bağlı Bayramözü köyünün tarihini, arşiv belgelerini, haberlerini ve şehir dışındaki köylüleri tek dijital çatıda buluşturan platform.','{"html": "<p><strong>Bayramözü Köyü</strong> platformu, eski adı Merdeşe olan köyün hafızasını birincil kaynaklara dayanarak dijital ortama taşır. Defterler, belgeler ve anlatılar kaynak künyeleriyle bir araya gelir.</p><h2>Kaynaklı köy tarihi</h2><p>Köy tarihi birincil ve akademik kaynaklara dayalı, künyeli metinlerle anlatılır. Osmanlı nüfus defterlerinden çıkarılan hane kayıtları çözümlenerek sunulur.</p><h2>Arşiv ve soy kütüğü</h2><p>Nüfus defteri arşivi, hane çözümlemeleri ve sülale ağacı birbirine bağlıdır; fotoğraf ve belge galerisi aynı yapıdan beslenir.</p><h2>Köy haberleri ve iletişim</h2><p>Haberler, duyurular ve şehir dışında yaşayan köylüler için bir iletişim ve dayanışma alanı sunulur. Okunabilirlik için yazı boyutu ayarı vardır.</p><h2>Öne çıkan özellikler</h2><ul><li>Kaynak künyeli köy tarihi</li><li>Osmanlı nüfus defteri arşivi ve hane çözümlemeleri</li><li>Soy kütüğü ve sülale ağacı</li><li>Köy haberleri ve duyurular</li><li>Fotoğraf ve belge galerisi</li><li>Erişilebilir yazı boyutu seçenekleri</li></ul>", "description": "Kaman/Kırşehir''e bağlı Bayramözü köyünün tarihini, arşiv belgelerini, haberlerini ve şehir dışındaki köylüleri tek dijital çatıda buluşturan platform.", "key_features": ["Kaynak künyeli köy tarihi", "Osmanlı nüfus defteri arşivi ve hane çözümlemeleri", "Soy kütüğü ve sülale ağacı", "Köy haberleri ve duyurular", "Fotoğraf ve belge galerisi", "Erişilebilir yazı boyutu seçenekleri"], "technologies_used": ["Next.js 16", "React 19", "TypeScript", "Fastify", "Drizzle ORM", "MySQL", "Bun", "Nginx"], "design_highlights": []}','Bayramözü Köyü ana sayfası: köyün hafızası, kaynaklarıyla','Bayramözü Köyü — Köy Tarihi ve Dijital Arşiv Platformu | Guezel Web Design','Bayramözü (Merdeşe) köyünün kaynaklı tarihi, Osmanlı nüfus defteri arşivi, soy kütüğü ve köy haberlerini bir araya getiren dijital platform.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `project_images_i18n` (`id`,`image_id`,`locale`,`alt`,`caption`,`created_at`,`updated_at`) VALUES ('d83029c0-603c-5451-a951-85ce07dceff9','c60f824e-1d7e-501c-9a9a-35643b4912fe','tr','Bayramözü Köyü ana sayfası: köyün hafızası, kaynaklarıyla',NULL,NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `alt`=VALUES(`alt`),`updated_at`=NOW(3);
INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('5a8a4772-4441-500e-b57d-b84a575e507f','a5713635-b3f4-5bcc-9582-421011585475','en','Bayramözü Village — Source-Based Village History and Digital Archive','bayramozu-koyu-dijital-arsiv-ve-koy-platformu','A platform that brings together the history, archive documents and news of Bayramözü village in Kaman/Kırşehir, and connects villagers living elsewhere.','{"html": "<p>The <strong>Bayramözü Village</strong> platform carries the memory of the village, formerly known as Merdeşe, into a digital space based on primary sources. Registers, documents and oral accounts are brought together with full citations.</p><h2>Source-based village history</h2><p>The history of the village is told through cited texts based on primary and academic sources. Household records extracted from Ottoman population registers are analysed and presented.</p><h2>Archive and family tree</h2><p>The population register archive, household analyses and family tree are linked to each other; the photo and document gallery is built on the same structure.</p><h2>Village news and community</h2><p>News, announcements and a space for villagers living in cities are provided. Adjustable text size supports readability.</p><h2>Key features</h2><ul><li>Village history with full citations</li><li>Ottoman population register archive and household analyses</li><li>Family tree and lineage records</li><li>Village news and announcements</li><li>Photo and document gallery</li><li>Accessible text size options</li></ul>", "description": "A platform that brings together the history, archive documents and news of Bayramözü village in Kaman/Kırşehir, and connects villagers living elsewhere.", "key_features": ["Village history with full citations", "Ottoman population register archive and household analyses", "Family tree and lineage records", "Village news and announcements", "Photo and document gallery", "Accessible text size options"], "technologies_used": ["Next.js 16", "React 19", "TypeScript", "Fastify", "Drizzle ORM", "MySQL", "Bun", "Nginx"], "design_highlights": []}','Bayramözü Village homepage: the village memory, with its sources','Bayramözü Village — Village History and Digital Archive | Guezel Web Design','Digital platform combining the cited history of Bayramözü (Merdeşe) village, an Ottoman population register archive, family trees and village news.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `project_images_i18n` (`id`,`image_id`,`locale`,`alt`,`caption`,`created_at`,`updated_at`) VALUES ('17edab0a-df5d-51fb-b311-6e98e07befd9','c60f824e-1d7e-501c-9a9a-35643b4912fe','en','Bayramözü Village homepage: the village memory, with its sources',NULL,NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `alt`=VALUES(`alt`),`updated_at`=NOW(3);
INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('aab8a5b1-304b-51fc-a678-7410f1f87162','a5713635-b3f4-5bcc-9582-421011585475','de','Dorf Bayramözü — Quellenbasierte Dorfgeschichte und digitales Archiv','bayramozu-koyu-dijital-arsiv-ve-koy-platformu','Eine Plattform, die Geschichte, Archivdokumente und Nachrichten des Dorfes Bayramözü (Kaman/Kırşehir) bündelt und auswärts lebende Dorfbewohner verbindet.','{"html": "<p>Die Plattform <strong>Dorf Bayramözü</strong> überträgt das Gedächtnis des früher Merdeşe genannten Dorfes auf Grundlage von Primärquellen in den digitalen Raum. Register, Dokumente und Erzählungen erscheinen mit vollständigen Quellenangaben.</p><h2>Quellenbasierte Dorfgeschichte</h2><p>Die Dorfgeschichte wird in belegten Texten auf Basis von Primär- und Fachquellen erzählt. Haushaltseinträge aus osmanischen Bevölkerungsregistern werden ausgewertet und dargestellt.</p><h2>Archiv und Stammbaum</h2><p>Registerarchiv, Haushaltsanalysen und Stammbaum sind miteinander verknüpft; die Foto- und Dokumentengalerie nutzt dieselbe Struktur.</p><h2>Dorfnachrichten und Gemeinschaft</h2><p>Nachrichten, Mitteilungen und ein Austauschbereich für auswärts lebende Dorfbewohner. Eine anpassbare Schriftgröße unterstützt die Lesbarkeit.</p><h2>Wichtige Funktionen</h2><ul><li>Dorfgeschichte mit Quellenangaben</li><li>Osmanisches Bevölkerungsregister und Haushaltsanalysen</li><li>Stammbaum und Familienlinien</li><li>Dorfnachrichten und Mitteilungen</li><li>Foto- und Dokumentengalerie</li><li>Barrierearme Schriftgrößen</li></ul>", "description": "Eine Plattform, die Geschichte, Archivdokumente und Nachrichten des Dorfes Bayramözü (Kaman/Kırşehir) bündelt und auswärts lebende Dorfbewohner verbindet.", "key_features": ["Dorfgeschichte mit Quellenangaben", "Osmanisches Bevölkerungsregister und Haushaltsanalysen", "Stammbaum und Familienlinien", "Dorfnachrichten und Mitteilungen", "Foto- und Dokumentengalerie", "Barrierearme Schriftgrößen"], "technologies_used": ["Next.js 16", "React 19", "TypeScript", "Fastify", "Drizzle ORM", "MySQL", "Bun", "Nginx"], "design_highlights": []}','Startseite Dorf Bayramözü: das Gedächtnis des Dorfes, mit Quellen','Dorf Bayramözü — Dorfgeschichte und digitales Archiv | Guezel Web Design','Digitale Plattform mit belegter Geschichte des Dorfes Bayramözü (Merdeşe), osmanischem Registerarchiv, Stammbäumen und Dorfnachrichten.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
