INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('6537386a-69da-5daf-a698-39c8f3db0515','d2defb09-34fa-5fbd-bf6c-05176f2f43a3','tr','SportoFlow — Yapay Zekâ Destekli Kişisel Longevity Platformu','sportoflow-yapay-zeka-destekli-longevity-platformu','Egzersiz, beslenme, uyku, takviye ve biyobelirteç takibini insan onaylı bir bilgi motoru ve yapay zekâ koçla birleştiren çok kiracılı SaaS.','{"html": "<p><strong>SportoFlow</strong>, uzun ve sağlıklı yaşam için kişisel bir işletim sistemi olarak tasarlandı. Bilimsel bilgiyi, ölçümleri ve günlük alışkanlıkları bir araya getirir; öneriler insan onayından geçer.</p><h2>İnsan onaylı bilgi motoru</h2><p>Longevity alanındaki yayınlar toplanır, iddialar kanıt düzeyiyle çıkarılır ve editör onayından sonra kişisel protokole yansır.</p><h2>Deterministik antrenman motoru</h2><p>Koşu, bisiklet, yüzme, triatlon ve kuvvet programları kurallarla üretilir; hacim artışı, yük oranı ve dinlenme haftası denetlenir. Yapay zekâ yalnız açıklar ve ince ayar yapar.</p><h2>Biyobelirteç ve ölçüm takibi</h2><p>Kan paneli değerleri normal ve optimal aralıklarla izlenir; yapılan ve kaçırılan antrenmanlar sonraki haftanın planını yeniden hesaplar.</p><h2>Öne çıkan özellikler</h2><ul><li>Çok kiracılı SaaS çekirdeği ve abonelik</li><li>İnsan onaylı longevity bilgi motoru</li><li>Branşa özel antrenman programları</li><li>Biyobelirteç ve kan paneli takibi</li><li>Uyarlanabilir haftalık plan</li><li>Giyilebilir cihaz entegrasyonu için adaptör yapısı</li></ul>", "description": "Egzersiz, beslenme, uyku, takviye ve biyobelirteç takibini insan onaylı bir bilgi motoru ve yapay zekâ koçla birleştiren çok kiracılı SaaS.", "key_features": ["Çok kiracılı SaaS çekirdeği ve abonelik", "İnsan onaylı longevity bilgi motoru", "Branşa özel antrenman programları", "Biyobelirteç ve kan paneli takibi", "Uyarlanabilir haftalık plan", "Giyilebilir cihaz entegrasyonu için adaptör yapısı"], "technologies_used": ["Next.js 16", "React 19", "TypeScript", "Shadcn UI", "React Query", "Bun", "Fastify", "Drizzle ORM", "MySQL", "Zod", "Stripe"], "design_highlights": []}','SportoFlow ana sayfası: sağlıklı yaşamınız yapay zekâ ile güçlensin','SportoFlow — Yapay Zekâ Destekli Longevity Platformu | Guezel Web Design','Egzersiz, beslenme, uyku ve biyobelirteç takibini insan onaylı bilgi motoru ve yapay zekâ koçla birleştiren çok kiracılı longevity SaaS platformu.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `project_images_i18n` (`id`,`image_id`,`locale`,`alt`,`caption`,`created_at`,`updated_at`) VALUES ('d7199386-f1fa-5f02-b3a4-2e3f74c8aa79','7256d036-5913-5446-b36e-4a381ec33368','tr','SportoFlow ana sayfası: sağlıklı yaşamınız yapay zekâ ile güçlensin',NULL,NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `alt`=VALUES(`alt`),`updated_at`=NOW(3);
INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('e4ee6270-1222-5428-91e4-2627f383fb2d','d2defb09-34fa-5fbd-bf6c-05176f2f43a3','en','SportoFlow — AI-Assisted Personal Longevity Platform','sportoflow-yapay-zeka-destekli-longevity-platformu','A multi-tenant SaaS combining exercise, nutrition, sleep, supplement and biomarker tracking with a human-approved knowledge engine and an AI coach.','{"html": "<p><strong>SportoFlow</strong> is designed as a personal operating system for a long and healthy life. It brings scientific knowledge, measurements and daily habits together; recommendations pass human review.</p><h2>Human-approved knowledge engine</h2><p>Longevity publications are collected, claims are extracted with their level of evidence and reach the personal protocol only after editorial approval.</p><h2>Deterministic training engine</h2><p>Running, cycling, swimming, triathlon and strength programmes are generated by rules; volume ramps, load ratios and deload weeks are checked. AI only explains and fine-tunes.</p><h2>Biomarker and measurement tracking</h2><p>Blood panel values are tracked against normal and optimal ranges; completed and missed workouts recalculate the following week.</p><h2>Key features</h2><ul><li>Multi-tenant SaaS core with subscriptions</li><li>Human-approved longevity knowledge engine</li><li>Sport-specific training programmes</li><li>Biomarker and blood panel tracking</li><li>Adaptive weekly plan</li><li>Adapter-based wearable integration</li></ul>", "description": "A multi-tenant SaaS combining exercise, nutrition, sleep, supplement and biomarker tracking with a human-approved knowledge engine and an AI coach.", "key_features": ["Multi-tenant SaaS core with subscriptions", "Human-approved longevity knowledge engine", "Sport-specific training programmes", "Biomarker and blood panel tracking", "Adaptive weekly plan", "Adapter-based wearable integration"], "technologies_used": ["Next.js 16", "React 19", "TypeScript", "Shadcn UI", "React Query", "Bun", "Fastify", "Drizzle ORM", "MySQL", "Zod", "Stripe"], "design_highlights": []}','SportoFlow homepage: empower your healthy life with AI','SportoFlow — AI-Assisted Longevity Platform | Guezel Web Design','Multi-tenant longevity SaaS combining exercise, nutrition, sleep and biomarker tracking with a human-approved knowledge engine and an AI coach.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `project_images_i18n` (`id`,`image_id`,`locale`,`alt`,`caption`,`created_at`,`updated_at`) VALUES ('f39b3e90-bfea-5e73-ad67-2099bc241557','7256d036-5913-5446-b36e-4a381ec33368','en','SportoFlow homepage: empower your healthy life with AI',NULL,NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `alt`=VALUES(`alt`),`updated_at`=NOW(3);
INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('4131d787-67af-5e12-a7db-48e95dd468ce','d2defb09-34fa-5fbd-bf6c-05176f2f43a3','de','SportoFlow — KI-gestützte persönliche Longevity-Plattform','sportoflow-yapay-zeka-destekli-longevity-platformu','Eine mandantenfähige SaaS, die Training, Ernährung, Schlaf, Supplements und Biomarker mit einer menschlich geprüften Wissensbasis und einem KI-Coach verbindet.','{"html": "<p><strong>SportoFlow</strong> ist als persönliches Betriebssystem für ein langes, gesundes Leben konzipiert. Es verbindet wissenschaftliches Wissen, Messwerte und Alltagsgewohnheiten; Empfehlungen werden menschlich geprüft.</p><h2>Menschlich geprüfte Wissensbasis</h2><p>Veröffentlichungen aus der Longevity-Forschung werden gesammelt, Aussagen mit Evidenzgrad extrahiert und erst nach redaktioneller Freigabe ins persönliche Protokoll übernommen.</p><h2>Deterministischer Trainingsplaner</h2><p>Lauf-, Rad-, Schwimm-, Triathlon- und Kraftprogramme entstehen regelbasiert; Umfangssteigerung, Belastungsverhältnis und Entlastungswochen werden geprüft. Die KI erklärt und justiert nur.</p><h2>Biomarker und Messwerte</h2><p>Blutwerte werden gegen Normal- und Optimalbereiche verfolgt; absolvierte und ausgelassene Einheiten berechnen die Folgewoche neu.</p><h2>Wichtige Funktionen</h2><ul><li>Mandantenfähiger SaaS-Kern mit Abonnements</li><li>Menschlich geprüfte Longevity-Wissensbasis</li><li>Sportartspezifische Trainingspläne</li><li>Biomarker- und Blutwerttracking</li><li>Adaptiver Wochenplan</li><li>Adapter-Architektur für Wearables</li></ul>", "description": "Eine mandantenfähige SaaS, die Training, Ernährung, Schlaf, Supplements und Biomarker mit einer menschlich geprüften Wissensbasis und einem KI-Coach verbindet.", "key_features": ["Mandantenfähiger SaaS-Kern mit Abonnements", "Menschlich geprüfte Longevity-Wissensbasis", "Sportartspezifische Trainingspläne", "Biomarker- und Blutwerttracking", "Adaptiver Wochenplan", "Adapter-Architektur für Wearables"], "technologies_used": ["Next.js 16", "React 19", "TypeScript", "Shadcn UI", "React Query", "Bun", "Fastify", "Drizzle ORM", "MySQL", "Zod", "Stripe"], "design_highlights": []}','SportoFlow Startseite: gesünder leben mit KI','SportoFlow — KI-gestützte Longevity-Plattform | Guezel Web Design','Mandantenfähige Longevity-SaaS: Training, Ernährung, Schlaf und Biomarker mit menschlich geprüfter Wissensbasis und KI-Coach verbunden.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
