INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('92a5460b-f2a9-52e8-8b13-53c2726e3ac6','317d4312-add2-5ced-9a72-4082b3681d43','tr','Ensotek Türkiye — Endüstriyel Soğutma Kulesi B2B Platformu','ensotek-com-tr-sogutma-kulesi-b2b-platformu','Türkiye pazarı için ürün kataloğu, doküman kütüphanesi ve çok dilli içerik yönetimi sunan endüstriyel soğutma kulesi B2B platformu.','{"html": "<p><strong>ensotek.com.tr</strong>, açık devre, kapalı devre ve evaporatif soğutma sistemleri üreten Ensotek''in Türkiye pazarına yönelik B2B platformudur. Ürün grupları, teknik dokümanlar ve teklif akışı tek yerde toplanır.</p><h2>Ürün grupları ve katalog</h2><p>Kapalı ve açık devre soğutma kuleleri ile yedek parçalar ürün gruplarına ayrılmış bir katalogda sunulur; katalog ve teklif çağrıları her sayfada erişilebilir.</p><h2>Doküman kütüphanesi</h2><p>Teknik dokümanlar ve kataloglar yönetim panelinden yüklenir ve ürünlerle ilişkilendirilir.</p><h2>Ortak altyapı</h2><p>Platform, Ensotek''in diğer siteleriyle ortak backend paketlerini paylaşır; içerik çok dillidir ve tamamı yönetim panelinden yönetilir.</p><h2>Öne çıkan özellikler</h2><ul><li>Yönetim paneli</li><li>Ürün ve katalog yönetimi</li><li>Doküman kütüphanesi</li><li>Çok dilli içerik</li><li>Teklif talebi akışı</li><li>Ortak backend paketleri</li></ul>", "description": "Türkiye pazarı için ürün kataloğu, doküman kütüphanesi ve çok dilli içerik yönetimi sunan endüstriyel soğutma kulesi B2B platformu.", "key_features": ["Yönetim paneli", "Ürün ve katalog yönetimi", "Doküman kütüphanesi", "Çok dilli içerik", "Teklif talebi akışı", "Ortak backend paketleri"], "technologies_used": ["Next.js", "React", "TypeScript", "Fastify", "Drizzle ORM", "MySQL", "Bun", "Zod", "next-intl", "Tailwind CSS", "React Query", "Redux Toolkit"], "design_highlights": []}','Ensotek Türkiye ana sayfası: endüstriyel soğutma sistemleri','Ensotek Türkiye — Soğutma Kulesi B2B Platformu | Guezel Web Design','Ensotek için geliştirilen Türkiye B2B platformu: soğutma kulesi ürün kataloğu, doküman kütüphanesi, teklif akışı ve çok dilli içerik yönetimi.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `project_images_i18n` (`id`,`image_id`,`locale`,`alt`,`caption`,`created_at`,`updated_at`) VALUES ('96e7f19b-7e5a-5326-abd6-640bacc1159f','2d18b45e-69b1-58ed-8bc7-c3754585ecb3','tr','Ensotek Türkiye ana sayfası: endüstriyel soğutma sistemleri',NULL,NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `alt`=VALUES(`alt`),`updated_at`=NOW(3);
INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('74f36a04-a1fc-5662-b5f2-f9c3f7e519e6','317d4312-add2-5ced-9a72-4082b3681d43','en','Ensotek Turkey — Industrial Cooling Tower B2B Platform','ensotek-com-tr-sogutma-kulesi-b2b-platformu','An industrial cooling tower B2B platform for the Turkish market with a product catalog, document library and multilingual content management.','{"html": "<p><strong>ensotek.com.tr</strong> is the B2B platform for the Turkish market of Ensotek, a manufacturer of open circuit, closed circuit and evaporative cooling systems. Product groups, technical documents and the quote flow live in one place.</p><h2>Product groups and catalog</h2><p>Closed and open circuit cooling towers and spare parts are presented in a catalog organised by product group; catalog and quote calls to action are available on every page.</p><h2>Document library</h2><p>Technical documents and catalogs are uploaded from the admin panel and linked to products.</p><h2>Shared foundation</h2><p>The platform shares backend packages with Ensotek''s other sites; content is multilingual and fully managed from the admin panel.</p><h2>Key features</h2><ul><li>Admin panel</li><li>Product and catalog management</li><li>Document library</li><li>Multilingual content</li><li>Quote request flow</li><li>Shared backend packages</li></ul>", "description": "An industrial cooling tower B2B platform for the Turkish market with a product catalog, document library and multilingual content management.", "key_features": ["Admin panel", "Product and catalog management", "Document library", "Multilingual content", "Quote request flow", "Shared backend packages"], "technologies_used": ["Next.js", "React", "TypeScript", "Fastify", "Drizzle ORM", "MySQL", "Bun", "Zod", "next-intl", "Tailwind CSS", "React Query", "Redux Toolkit"], "design_highlights": []}','Ensotek Turkey homepage: industrial cooling systems','Ensotek Turkey — Cooling Tower B2B Platform | Guezel Web Design','Turkish B2B platform built for Ensotek: cooling tower product catalog, document library, quote flow and multilingual content management.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `project_images_i18n` (`id`,`image_id`,`locale`,`alt`,`caption`,`created_at`,`updated_at`) VALUES ('910fac71-8b48-5705-a416-0deb652beda6','2d18b45e-69b1-58ed-8bc7-c3754585ecb3','en','Ensotek Turkey homepage: industrial cooling systems',NULL,NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `alt`=VALUES(`alt`),`updated_at`=NOW(3);
INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('fe57de34-775f-5e9a-bbd2-03ef312467ea','317d4312-add2-5ced-9a72-4082b3681d43','de','Ensotek Türkei — B2B-Plattform für industrielle Kühltürme','ensotek-com-tr-sogutma-kulesi-b2b-platformu','Eine B2B-Plattform für industrielle Kühltürme im türkischen Markt mit Produktkatalog, Dokumentenbibliothek und mehrsprachiger Inhaltsverwaltung.','{"html": "<p><strong>ensotek.com.tr</strong> ist die B2B-Plattform von Ensotek für den türkischen Markt — einem Hersteller offener, geschlossener und evaporativer Kühlsysteme. Produktgruppen, technische Dokumente und der Angebotsprozess sind an einem Ort gebündelt.</p><h2>Produktgruppen und Katalog</h2><p>Offene und geschlossene Kühltürme sowie Ersatzteile erscheinen in einem nach Produktgruppen gegliederten Katalog; Katalog- und Angebotsaufrufe sind auf jeder Seite erreichbar.</p><h2>Dokumentenbibliothek</h2><p>Technische Unterlagen und Kataloge werden im Admin-Panel hochgeladen und mit Produkten verknüpft.</p><h2>Gemeinsame Basis</h2><p>Die Plattform teilt Backend-Pakete mit den übrigen Ensotek-Sites; Inhalte sind mehrsprachig und vollständig im Admin-Panel pflegbar.</p><h2>Wichtige Funktionen</h2><ul><li>Admin-Panel</li><li>Produkt- und Katalogverwaltung</li><li>Dokumentenbibliothek</li><li>Mehrsprachige Inhalte</li><li>Angebotsanfragen</li><li>Gemeinsame Backend-Pakete</li></ul>", "description": "Eine B2B-Plattform für industrielle Kühltürme im türkischen Markt mit Produktkatalog, Dokumentenbibliothek und mehrsprachiger Inhaltsverwaltung.", "key_features": ["Admin-Panel", "Produkt- und Katalogverwaltung", "Dokumentenbibliothek", "Mehrsprachige Inhalte", "Angebotsanfragen", "Gemeinsame Backend-Pakete"], "technologies_used": ["Next.js", "React", "TypeScript", "Fastify", "Drizzle ORM", "MySQL", "Bun", "Zod", "next-intl", "Tailwind CSS", "React Query", "Redux Toolkit"], "design_highlights": []}','Ensotek Türkei Startseite: industrielle Kühlsysteme','Ensotek Türkei — B2B-Plattform für Kühltürme | Guezel Web Design','Türkische B2B-Plattform für Ensotek: Kühlturm-Produktkatalog, Dokumentenbibliothek, Angebotsprozess und mehrsprachige Inhaltsverwaltung.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
