INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('9d57adf5-27f7-5697-98be-a486c0052859','422f117d-1333-5b61-9103-dcc51b94ef3c','tr','Kühlturm — Almanca ve İngilizce Soğutma Kulesi B2B Platformu','kuhlturm-sogutma-kulesi-b2b-platformu','Ensotek alt markası Kühlturm için bağımsız API, yönetim paneli ve veri alanına sahip Almanca/İngilizce B2B soğutma kulesi platformu.','{"html": "<p><strong>Kühlturm</strong>, Ensotek''in Almanca konuşulan pazarlara yönelik alt markasıdır. Platform; elektrik santralleri, sanayi tesisleri ve ticari binalar için soğutma kulesi çözümlerini katalog ve teklif akışıyla sunar.</p><h2>Bağımsız marka altyapısı</h2><p>Kühlturm, Ensotek ile kod tabanını paylaşırken kendi API''sine, yönetim paneline ve veritabanına sahiptir; markalar birbirinin verisini görmez.</p><h2>Katalog ve teklif</h2><p>Ürünler, referanslar ve teknik kütüphane Almanca ve İngilizce sunulur; katalog talebi ve teklif formu her sayfada görünür.</p><h2>API dokümantasyonu</h2><p>Arka uç Swagger ile belgelenmiştir; içerik ve müşteri dokümanları yönetim panelinden yönetilir.</p><h2>Öne çıkan özellikler</h2><ul><li>Almanca/İngilizce içerik</li><li>Bağımsız API ve veritabanı</li><li>Yönetim paneli</li><li>Katalog ve teklif talebi</li><li>Müşteri doküman yönetimi</li><li>Swagger API dokümantasyonu</li></ul>", "description": "Ensotek alt markası Kühlturm için bağımsız API, yönetim paneli ve veri alanına sahip Almanca/İngilizce B2B soğutma kulesi platformu.", "key_features": ["Almanca/İngilizce içerik", "Bağımsız API ve veritabanı", "Yönetim paneli", "Katalog ve teklif talebi", "Müşteri doküman yönetimi", "Swagger API dokümantasyonu"], "technologies_used": ["Next.js", "React", "TypeScript", "Fastify", "Drizzle ORM", "MySQL", "Bun", "Zod", "next-intl", "Tailwind CSS"], "design_highlights": []}','Kühlturm ana sayfası: endüstriyel soğutma kulesi çözümleri','Kühlturm — Soğutma Kulesi B2B Platformu | Guezel Web Design','Ensotek alt markası Kühlturm için Almanca ve İngilizce B2B soğutma kulesi platformu: bağımsız API, yönetim paneli, katalog ve teklif akışı.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
