INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('f105bc63-7912-5978-84d3-070a33631736','422f117d-1333-5b61-9103-dcc51b94ef3c','en','Kühlturm — German and English Cooling Tower B2B Platform','kuhlturm-sogutma-kulesi-b2b-platformu','A German/English B2B cooling tower platform for the Ensotek sub-brand Kühlturm, with its own API, admin panel and data store.','{"html": "<p><strong>Kühlturm</strong> is Ensotek''s sub-brand for German-speaking markets. The platform presents cooling tower solutions for power plants, industrial facilities and commercial buildings with a catalog and quote flow.</p><h2>Independent brand foundation</h2><p>Kühlturm shares its codebase with Ensotek but has its own API, admin panel and database; the brands never see each other''s data.</p><h2>Catalog and quote</h2><p>Products, references and the technical library are available in German and English; catalog requests and the quote form are visible on every page.</p><h2>API documentation</h2><p>The backend is documented with Swagger; content and customer documents are managed from the admin panel.</p><h2>Key features</h2><ul><li>German/English content</li><li>Independent API and database</li><li>Admin panel</li><li>Catalog and quote requests</li><li>Customer document management</li><li>Swagger API documentation</li></ul>", "description": "A German/English B2B cooling tower platform for the Ensotek sub-brand Kühlturm, with its own API, admin panel and data store.", "key_features": ["German/English content", "Independent API and database", "Admin panel", "Catalog and quote requests", "Customer document management", "Swagger API documentation"], "technologies_used": ["Next.js", "React", "TypeScript", "Fastify", "Drizzle ORM", "MySQL", "Bun", "Zod", "next-intl", "Tailwind CSS"], "design_highlights": []}','Kühlturm homepage: industrial cooling tower solutions','Kühlturm — Cooling Tower B2B Platform | Guezel Web Design','German and English B2B cooling tower platform for the Ensotek sub-brand Kühlturm: independent API, admin panel, catalog and quote flow.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `project_images_i18n` (`id`,`image_id`,`locale`,`alt`,`caption`,`created_at`,`updated_at`) VALUES ('31971939-8a4b-52d1-97d3-d39d57afa653','2612c088-2f05-5e02-9aaa-1249589d8cb3','en','Kühlturm homepage: industrial cooling tower solutions',NULL,NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `alt`=VALUES(`alt`),`updated_at`=NOW(3);
INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('fc997857-a06e-5f89-bc94-3d62e0934ca4','422f117d-1333-5b61-9103-dcc51b94ef3c','de','Kühlturm — B2B-Plattform für Kühltürme auf Deutsch und Englisch','kuhlturm-sogutma-kulesi-b2b-platformu','Eine deutsch-englische B2B-Plattform für Kühltürme der Ensotek-Tochtermarke Kühlturm mit eigener API, eigenem Admin-Panel und eigenem Datenbestand.','{"html": "<p><strong>Kühlturm</strong> ist die Ensotek-Marke für den deutschsprachigen Raum. Die Plattform präsentiert Kühlturmlösungen für Kraftwerke, Industrieanlagen und Gewerbegebäude mit Katalog und Angebotsprozess.</p><h2>Eigenständige Markenbasis</h2><p>Kühlturm teilt die Codebasis mit Ensotek, verfügt aber über eigene API, eigenes Admin-Panel und eigene Datenbank; die Marken sehen die Daten der jeweils anderen nicht.</p><h2>Katalog und Angebot</h2><p>Produkte, Referenzen und die technische Bibliothek liegen auf Deutsch und Englisch vor; Katalogwunsch und Angebotsformular sind auf jeder Seite sichtbar.</p><h2>API-Dokumentation</h2><p>Das Backend ist mit Swagger dokumentiert; Inhalte und Kundendokumente werden im Admin-Panel verwaltet.</p><h2>Wichtige Funktionen</h2><ul><li>Inhalte auf Deutsch und Englisch</li><li>Eigenständige API und Datenbank</li><li>Admin-Panel</li><li>Katalog- und Angebotsanfragen</li><li>Verwaltung von Kundendokumenten</li><li>Swagger-API-Dokumentation</li></ul>", "description": "Eine deutsch-englische B2B-Plattform für Kühltürme der Ensotek-Tochtermarke Kühlturm mit eigener API, eigenem Admin-Panel und eigenem Datenbestand.", "key_features": ["Inhalte auf Deutsch und Englisch", "Eigenständige API und Datenbank", "Admin-Panel", "Katalog- und Angebotsanfragen", "Verwaltung von Kundendokumenten", "Swagger-API-Dokumentation"], "technologies_used": ["Next.js", "React", "TypeScript", "Fastify", "Drizzle ORM", "MySQL", "Bun", "Zod", "next-intl", "Tailwind CSS"], "design_highlights": []}','Kühlturm Startseite: industrielle Kühlturmlösungen','Kühlturm — B2B-Plattform für Kühltürme | Guezel Web Design','Deutsch-englische B2B-Plattform für die Ensotek-Marke Kühlturm: eigenständige API, Admin-Panel, Katalog und Angebotsprozess.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
