INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('e0bbb520-e301-5e17-8ba2-9352ef5ae402','e3cf5ffb-ab1b-5c39-9114-6e3339c25113','tr','TeklifRota — İhracat Teklifi ve Lojistik SaaS','teklifrota-ihracat-teklif-ve-lojistik-saas','İhracat tekliflerini, revizyonları, proforma ve çeki listesini, navlun, onay ve sevkiyat süreçlerini tek denetlenebilir akışta yöneten çok kiracılı B2B platform.','{"html": "<p><strong>TeklifRota</strong>, ihracat ekiplerinin alıcıdan sevkiyata kadar tüm süreci tek rotada yürütmesi için geliştirildi. Tekliflerin ve lojistik belgelerinin elektronik tablolar ile kopuk dosyalarda hazırlanmasından doğan tutarsızlıkları ortadan kaldırır.</p><h2>Adımlı teklif hazırlama</h2><p>Müşteri ve ürün kayıtlarından teklif üretilir; döviz ve teslim şekilleri, revizyon geçmişi ve onay adımları aynı kayıtta tutulur.</p><h2>Belge üretimi</h2><p>Proforma fatura ve çeki listesi tekliften türetilir; aynı müşteri ve ürün bilgisi her aşamada korunur.</p><h2>Navlun ve sevkiyat</h2><p>Navlun teklifleri kanıtlanır, sevkiyat açılır ve operasyon takibi teslimata kadar tek ekrandan izlenir.</p><h2>Öne çıkan özellikler</h2><ul><li>Çok kiracılı B2B SaaS</li><li>Adımlı teklif iş akışı</li><li>Revizyon geçmişi ve onay</li><li>Proforma ve çeki listesi üretimi</li><li>Navlun karşılaştırma ve sevkiyat takibi</li><li>Gümrük kaydı tabanlı alıcı araması</li></ul>", "description": "İhracat tekliflerini, revizyonları, proforma ve çeki listesini, navlun, onay ve sevkiyat süreçlerini tek denetlenebilir akışta yöneten çok kiracılı B2B platform.", "key_features": ["Çok kiracılı B2B SaaS", "Adımlı teklif iş akışı", "Revizyon geçmişi ve onay", "Proforma ve çeki listesi üretimi", "Navlun karşılaştırma ve sevkiyat takibi", "Gümrük kaydı tabanlı alıcı araması"], "technologies_used": ["Next.js", "React", "TypeScript", "Fastify", "MySQL", "Drizzle ORM", "Docker", "Nginx"], "design_highlights": []}','TeklifRota ana sayfası: ihracatta alıcıdan sevkiyata tek rota','TeklifRota — İhracat Teklifi ve Lojistik SaaS | Guezel Web Design','İhracat teklifleri, revizyonlar, proforma, çeki listesi, navlun ve sevkiyat süreçlerini tek denetlenebilir akışta yöneten çok kiracılı B2B SaaS.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `project_images_i18n` (`id`,`image_id`,`locale`,`alt`,`caption`,`created_at`,`updated_at`) VALUES ('74ebac75-88eb-5274-b408-839daa728c81','e4c281d6-db96-5c60-9295-ed2b85fabddf','tr','TeklifRota ana sayfası: ihracatta alıcıdan sevkiyata tek rota',NULL,NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `alt`=VALUES(`alt`),`updated_at`=NOW(3);
INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('961bd611-3711-5a8b-b92c-276287c42be4','e3cf5ffb-ab1b-5c39-9114-6e3339c25113','en','TeklifRota — Export Quotation and Logistics SaaS','teklifrota-ihracat-teklif-ve-lojistik-saas','A multi-tenant B2B platform managing export quotes, revisions, proforma invoices, packing lists, freight, approvals and shipments in one auditable flow.','{"html": "<p><strong>TeklifRota</strong> lets export teams run the whole process from buyer to shipment on one route. It removes the inconsistencies caused by preparing quotes and logistics documents in spreadsheets and scattered files.</p><h2>Step-by-step quoting</h2><p>Quotes are generated from customer and product records; currencies, Incoterms, revision history and approval steps stay on the same record.</p><h2>Document generation</h2><p>Proforma invoices and packing lists are derived from the quote; the same customer and product data is preserved at every stage.</p><h2>Freight and shipment</h2><p>Freight quotes are documented, shipments are opened and operations are tracked from a single screen until delivery.</p><h2>Key features</h2><ul><li>Multi-tenant B2B SaaS</li><li>Step-by-step quote workflow</li><li>Revision history and approvals</li><li>Proforma and packing list generation</li><li>Freight comparison and shipment tracking</li><li>Buyer search based on customs records</li></ul>", "description": "A multi-tenant B2B platform managing export quotes, revisions, proforma invoices, packing lists, freight, approvals and shipments in one auditable flow.", "key_features": ["Multi-tenant B2B SaaS", "Step-by-step quote workflow", "Revision history and approvals", "Proforma and packing list generation", "Freight comparison and shipment tracking", "Buyer search based on customs records"], "technologies_used": ["Next.js", "React", "TypeScript", "Fastify", "MySQL", "Drizzle ORM", "Docker", "Nginx"], "design_highlights": []}','TeklifRota homepage: one route from buyer to shipment','TeklifRota — Export Quotation and Logistics SaaS | Guezel Web Design','Multi-tenant B2B SaaS managing export quotes, revisions, proforma invoices, packing lists, freight and shipments in one auditable workflow.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `project_images_i18n` (`id`,`image_id`,`locale`,`alt`,`caption`,`created_at`,`updated_at`) VALUES ('4fab3ef3-bdbf-5657-b26e-a6c7acfebf6c','e4c281d6-db96-5c60-9295-ed2b85fabddf','en','TeklifRota homepage: one route from buyer to shipment',NULL,NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `alt`=VALUES(`alt`),`updated_at`=NOW(3);
INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('38bf9205-2455-54b8-8904-8ba7158aea74','e3cf5ffb-ab1b-5c39-9114-6e3339c25113','de','TeklifRota — SaaS für Exportangebote und Logistik','teklifrota-ihracat-teklif-ve-lojistik-saas','Eine mandantenfähige B2B-Plattform für Exportangebote, Revisionen, Proforma-Rechnungen, Packlisten, Fracht, Freigaben und Versand in einem nachvollziehbaren Ablauf.','{"html": "<p><strong>TeklifRota</strong> ermöglicht Exportteams, den gesamten Prozess vom Käufer bis zum Versand auf einer Route abzuwickeln. Die Plattform beseitigt Inkonsistenzen aus Tabellen und verstreuten Dateien.</p><h2>Angebotserstellung in Schritten</h2><p>Angebote entstehen aus Kunden- und Produktdaten; Währungen, Incoterms, Revisionsverlauf und Freigaben bleiben am selben Datensatz.</p><h2>Dokumentenerstellung</h2><p>Proforma-Rechnung und Packliste werden aus dem Angebot abgeleitet; Kunden- und Produktdaten bleiben in jeder Phase konsistent.</p><h2>Fracht und Versand</h2><p>Frachtangebote werden belegt, Sendungen eröffnet und bis zur Zustellung auf einem Bildschirm verfolgt.</p><h2>Wichtige Funktionen</h2><ul><li>Mandantenfähige B2B-SaaS</li><li>Schrittweiser Angebotsprozess</li><li>Revisionsverlauf und Freigaben</li><li>Proforma- und Packlistenerstellung</li><li>Frachtvergleich und Sendungsverfolgung</li><li>Käufersuche auf Basis von Zolldaten</li></ul>", "description": "Eine mandantenfähige B2B-Plattform für Exportangebote, Revisionen, Proforma-Rechnungen, Packlisten, Fracht, Freigaben und Versand in einem nachvollziehbaren Ablauf.", "key_features": ["Mandantenfähige B2B-SaaS", "Schrittweiser Angebotsprozess", "Revisionsverlauf und Freigaben", "Proforma- und Packlistenerstellung", "Frachtvergleich und Sendungsverfolgung", "Käufersuche auf Basis von Zolldaten"], "technologies_used": ["Next.js", "React", "TypeScript", "Fastify", "MySQL", "Drizzle ORM", "Docker", "Nginx"], "design_highlights": []}','TeklifRota Startseite: eine Route vom Käufer bis zum Versand','TeklifRota — SaaS für Exportangebote und Logistik | Guezel Web Design','Mandantenfähige B2B-SaaS für Exportangebote, Revisionen, Proforma, Packlisten, Fracht und Versand in einem nachvollziehbaren Ablauf.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
