INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('d85e7b6a-36a2-559e-9610-6055f2436477','3e0e49c5-6bd8-5d6c-927c-d45cc55b6a3d','tr','Aurora Global — B2B Rulman Kataloğu ve Teklif Sitesi','aurora-global-b2b-rulman-katalogu-ve-teklif-sitesi','Birleşik Krallık merkezli otomotiv ve endüstriyel yedek parça tedarikçisi için teknik rulman kataloğu ve teklif talebi akışına sahip çok dilli B2B web sitesi.','{"html": "<p><strong>Aurora Global</strong>, Avrupa sanayisine teknik olarak doğrulanmış rulman tedarik eden Birleşik Krallık merkezli bir firmadır. Site, rulman öncelikli konumlandırmayı teknik katalog ve teklif talebi akışıyla destekler.</p><h2>Teknik rulman kataloğu</h2><p>461 kayıtlı teknik rulman kataloğu marka ve teknik özelliklerle aranabilir; her ürün teklif talebine bağlanır.</p><h2>Teklif talebi (RFQ)</h2><p>Teklif formu ve talepler yönetim panelinden takip edilir; içeriğin tamamı veritabanından yönetilir.</p><h2>Çok dilli yapı ve görünürlük</h2><p>İngilizce ve Türkçe içerik yerelleştirilmiş URL yapısıyla sunulur; SSS yapısal verisi, llms.txt ve site haritası arama motorları ve yapay zekâ aramaları için hazırdır.</p><h2>Öne çıkan özellikler</h2><ul><li>461 kayıtlı teknik rulman kataloğu</li><li>Teklif talebi (RFQ) formu ve yönetimi</li><li>İngilizce/Türkçe yerelleştirilmiş URL yapısı</li><li>Veritabanından yönetilen içerik</li><li>SSS ve FAQPage yapısal verisi</li><li>llms.txt ve site haritası</li></ul>", "description": "Birleşik Krallık merkezli otomotiv ve endüstriyel yedek parça tedarikçisi için teknik rulman kataloğu ve teklif talebi akışına sahip çok dilli B2B web sitesi.", "key_features": ["461 kayıtlı teknik rulman kataloğu", "Teklif talebi (RFQ) formu ve yönetimi", "İngilizce/Türkçe yerelleştirilmiş URL yapısı", "Veritabanından yönetilen içerik", "SSS ve FAQPage yapısal verisi", "llms.txt ve site haritası"], "technologies_used": ["Next.js 16", "React 19", "TypeScript", "Tailwind CSS 4", "Fastify", "Bun", "Drizzle ORM", "MySQL", "Nginx", "PM2"], "design_highlights": []}','Aurora Global ana sayfası: Avrupa sanayisi için hassas rulman tedariki','Aurora Global — B2B Rulman Kataloğu ve Teklif Sitesi | Guezel Web Design','Birleşik Krallık merkezli yedek parça tedarikçisi için 461 kayıtlı teknik rulman kataloğu ve teklif talebi akışına sahip çok dilli B2B web sitesi.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `project_images_i18n` (`id`,`image_id`,`locale`,`alt`,`caption`,`created_at`,`updated_at`) VALUES ('0a7ac850-06af-5f5f-b1f4-2e3708a0cac7','e485fa3f-b5aa-5265-a7f7-c7fd152d4ff1','tr','Aurora Global ana sayfası: Avrupa sanayisi için hassas rulman tedariki',NULL,NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `alt`=VALUES(`alt`),`updated_at`=NOW(3);
INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('334d6f4c-47b1-50d0-bb4b-eb2beb8c936b','3e0e49c5-6bd8-5d6c-927c-d45cc55b6a3d','en','Aurora Global — B2B Bearing Catalog and Quote Website','aurora-global-b2b-rulman-katalogu-ve-teklif-sitesi','A multilingual B2B website with a technical bearing catalog and a request-for-quote flow for a UK-based automotive and industrial spare parts supplier.','{"html": "<p><strong>Aurora Global</strong> is a UK-based supplier of technically verified bearings for European industry. The website supports its bearing-first positioning with a technical catalog and a request-for-quote flow.</p><h2>Technical bearing catalog</h2><p>A technical catalog of 461 bearings is searchable by brand and specification; every product links to a quote request.</p><h2>Request for quote (RFQ)</h2><p>The quote form and incoming requests are tracked in the admin panel; all content is managed from the database.</p><h2>Multilingual structure and visibility</h2><p>English and Turkish content uses localised URLs; FAQ structured data, llms.txt and the sitemap prepare the site for search engines and AI search.</p><h2>Key features</h2><ul><li>Technical catalog of 461 bearings</li><li>RFQ form and request management</li><li>Localised English/Turkish URLs</li><li>Database-managed content</li><li>FAQ and FAQPage structured data</li><li>llms.txt and sitemap</li></ul>", "description": "A multilingual B2B website with a technical bearing catalog and a request-for-quote flow for a UK-based automotive and industrial spare parts supplier.", "key_features": ["Technical catalog of 461 bearings", "RFQ form and request management", "Localised English/Turkish URLs", "Database-managed content", "FAQ and FAQPage structured data", "llms.txt and sitemap"], "technologies_used": ["Next.js 16", "React 19", "TypeScript", "Tailwind CSS 4", "Fastify", "Bun", "Drizzle ORM", "MySQL", "Nginx", "PM2"], "design_highlights": []}','Aurora Global homepage: precision bearing supply for European industry','Aurora Global — B2B Bearing Catalog and Quote Website | Guezel Web Design','Multilingual B2B website for a UK-based spare parts supplier, with a technical catalog of 461 bearings and a request-for-quote flow.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `project_images_i18n` (`id`,`image_id`,`locale`,`alt`,`caption`,`created_at`,`updated_at`) VALUES ('e9523170-af02-5dcf-8cc6-5af8d41501e0','e485fa3f-b5aa-5265-a7f7-c7fd152d4ff1','en','Aurora Global homepage: precision bearing supply for European industry',NULL,NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `alt`=VALUES(`alt`),`updated_at`=NOW(3);
INSERT INTO `projects_i18n` (`id`,`project_id`,`locale`,`title`,`slug`,`summary`,`content`,`featured_image_alt`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('35cdeee8-fc64-5d96-979f-75252ea34f0f','3e0e49c5-6bd8-5d6c-927c-d45cc55b6a3d','de','Aurora Global — B2B-Wälzlagerkatalog und Angebotswebsite','aurora-global-b2b-rulman-katalogu-ve-teklif-sitesi','Eine mehrsprachige B2B-Website mit technischem Wälzlagerkatalog und Angebotsanfrage für einen britischen Lieferanten von Automobil- und Industrieersatzteilen.','{"html": "<p><strong>Aurora Global</strong> ist ein britischer Lieferant technisch geprüfter Wälzlager für die europäische Industrie. Die Website stützt die Positionierung als Lagerspezialist mit technischem Katalog und Angebotsanfrage.</p><h2>Technischer Wälzlagerkatalog</h2><p>Ein technischer Katalog mit 461 Lagern ist nach Marke und Spezifikation durchsuchbar; jedes Produkt führt zur Angebotsanfrage.</p><h2>Angebotsanfrage (RFQ)</h2><p>Formular und eingehende Anfragen werden im Admin-Panel verfolgt; sämtliche Inhalte werden aus der Datenbank verwaltet.</p><h2>Mehrsprachigkeit und Sichtbarkeit</h2><p>Englische und türkische Inhalte nutzen lokalisierte URLs; FAQ-Strukturdaten, llms.txt und Sitemap bereiten die Site auf Suchmaschinen und KI-Suche vor.</p><h2>Wichtige Funktionen</h2><ul><li>Technischer Katalog mit 461 Wälzlagern</li><li>RFQ-Formular und Anfrageverwaltung</li><li>Lokalisierte englische/türkische URLs</li><li>Datenbankgestützte Inhalte</li><li>FAQ- und FAQPage-Strukturdaten</li><li>llms.txt und Sitemap</li></ul>", "description": "Eine mehrsprachige B2B-Website mit technischem Wälzlagerkatalog und Angebotsanfrage für einen britischen Lieferanten von Automobil- und Industrieersatzteilen.", "key_features": ["Technischer Katalog mit 461 Wälzlagern", "RFQ-Formular und Anfrageverwaltung", "Lokalisierte englische/türkische URLs", "Datenbankgestützte Inhalte", "FAQ- und FAQPage-Strukturdaten", "llms.txt und Sitemap"], "technologies_used": ["Next.js 16", "React 19", "TypeScript", "Tailwind CSS 4", "Fastify", "Bun", "Drizzle ORM", "MySQL", "Nginx", "PM2"], "design_highlights": []}','Aurora Global Startseite: Präzisionswälzlager für die europäische Industrie','Aurora Global — B2B-Wälzlagerkatalog und Angebote | Guezel Web Design','Mehrsprachige B2B-Website für einen britischen Ersatzteillieferanten mit technischem Katalog von 461 Wälzlagern und Angebotsanfrage.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`summary`=VALUES(`summary`),`content`=VALUES(`content`),`featured_image_alt`=VALUES(`featured_image_alt`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
